-- Migrazione 0007: tabella testi_ui per testi i18n modificabili dal DB
-- Ogni riga = una chiave + una lingua. PK composta (chiave, lang).
-- Il codice usa: DB sovrascrive hardcoded, fallback al codice se chiave mancante.

CREATE TABLE IF NOT EXISTS testi_ui (
  chiave TEXT NOT NULL,
  lang   TEXT NOT NULL CHECK(lang IN ('it','en','fr','es','de')),
  valore TEXT NOT NULL DEFAULT '',
  updated_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (chiave, lang)
);

-- ─── INSERT testi IT ──────────────────────────────────────────────────────────
-- Solo lingua IT (opzione A). Le altre lingue restano hardcoded nel codice.

INSERT OR IGNORE INTO testi_ui (chiave, lang, valore) VALUES
('title',               'it', 'Sindrome ReNU Italia APS'),
('subtitle',            'it', 'Insieme, facciamo la differenza'),
('tagline',             'it', 'Una condizione genetica di nuova identificazione. Uno sforzo di ricerca coordinato a livello globale.'),
('hero_text',           'it', 'La sindrome di ReNU è una condizione complessa che coinvolge ogni giorno <strong>bambini, ragazzi e famiglie</strong>. Questo spazio nasce per offrire informazioni chiare, orientamento concreto e la forza di una comunità che condivide lo stesso percorso.'),
('hero_desc',           'it', 'La Sindrome ReNU è causata da varianti patogene del gene RNU4-2. Attualmente sono <strong>~250 i casi accertati nel mondo</strong> (12-14 in Italia). Le varianti patogene si concentrano in soli <a href="https://rarediseasegenomics.org/blog/saturation-genome-editing-of-rnu4-2" target="_blank" class="text-sky-200 hover:underline font-semibold">13 posizioni</a> degli oltre 3 miliardi di paia di basi del genoma! Siamo qui per <strong>supportare le famiglie italiane</strong> e offrire un aiuto concreto ai bambini ReNU.'),
('btn_diagnosis',       'it', 'DONA ORA – SOSTIENI LE FAMIGLIE RENU'),
('btn_diagnosis_sub',   'it', 'Ogni contributo fa la differenza. Grazie.'),
('btn_info',            'it', 'VUOI MAGGIORI INFORMAZIONI? CLICCA QUI'),
('btn_info_sub',        'it', 'Contattaci per informazioni sulla Sindrome ReNU'),
