('about_vision',            'it', 'Problemi visivi'),
('about_vision_items',      'it', 'Ipoplasia del nervo ottico, CVI (compromissione visiva corticale), strabismo, nistagmo'),
('about_face',              'it', 'Caratteristiche del viso'),
('about_face_items',        'it', 'Viso miopatico, epicanto, radice nasale larga, narici anteverse, grandi orecchie, guance piene'),
('about_muscle',            'it', 'Tono muscolare'),
('about_muscle_items',      'it', 'Ipotonia (basso tono muscolare) o debolezza muscolare'),
('about_mobility',          'it', 'Mobilità'),
('about_mobility_items',    'it', 'Ritardo nel cammino o incapacità di camminare'),
('about_growth',            'it', 'Crescita'),
